"""Builds python/parsons-u5.js (10 Parsons problems per lesson) and python/trace-u5.js (10 code-tracing problems per lesson) for Unit 5 (functions, parameters, return values, libraries, procedures).
Same engine and checks as gen_u4pt.py (every program is RUN; nothing is written unless every check passes).   usage: python3 tools/parsons/gen_u5pt.py [lesson ids]"""
import sys, os, json, subprocess
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE)
ROOT = os.path.dirname(os.path.dirname(HERE))
import gen_u4pt as G
from u5_shapes import SH
wk = json.loads(subprocess.run(['node', '-e', 'global.window={};require("%s/python/workplace.js");console.log(JSON.stringify(Object.fromEntries(Object.entries(window.PY_WORK).filter(([k])=>/^a15[1-6]$/.test(k)).map(([k,v])=>[k,v.brand]))))' % ROOT], capture_output=True, text=True).stdout)
NAMES = [('u5l1', '5.1', 'Functions and Parameters', 'a151'), ('u5l2', '5.2', 'Multiple Parameters', 'a152'), ('u5l3', '5.3', 'Return Values', 'a153'),
         ('u5l4', '5.4', 'Return Values with Decisions and Loops', 'a154'), ('u5l5', '5.5', 'Libraries and APIs', 'a155'), ('u5l6', '5.6', 'Procedures and the Create Task', 'a156')]
def nice(n): return n.title() if n.isupper() or n.islower() else n
G.LESSONS = [(i, n, t, nice(wk[a]['name']), wk[a]['color'], wk[a]['head']) for (i, n, t, a) in NAMES]
G.SH = SH
if __name__ == '__main__':
    only = sys.argv[1:]
    P, T = G.main(only)
    if only: print('checked', ', '.join(only), '| Parsons', sum(len(v['problems']) for v in P.values()), '| traces', sum(len(v['traces']) for v in T.values()), '| valid orders per problem:', [len(p['valid']) for v in P.values() for p in v['problems']])
    else:
        dump = lambda o: json.dumps(o, ensure_ascii=False, separators=(',', ':'))
        open(os.path.join(ROOT, 'python', 'parsons-u5.js'), 'w', encoding='utf-8').write('/* GENERATED by tools/parsons/gen_u5pt.py. Do not edit by hand. */\nwindow.PARSONS5 = ' + dump(dict(lessons=P)) + ';\n')
        open(os.path.join(ROOT, 'python', 'trace-u5.js'), 'w', encoding='utf-8').write('/* GENERATED by tools/parsons/gen_u5pt.py. Do not edit by hand. */\nwindow.TRACES5 = ' + dump(T) + ';\n')
        print('OK: %d lessons, %d Parsons, %d traces' % (len(P), sum(len(v['problems']) for v in P.values()), sum(len(v['traces']) for v in T.values())))
